private int calc(char c) {
    int[][] len = new int[N][N];
    for (var is : len)
        fill(is, infI);

    Deque<int[]> que = new ArrayDeque<>();
    if (c == 'R') {
        if (S[0][0] == c) {
            len[0][0] = 0;
            que.add(new int[]{0, 0, 0});
        } else {
            len[0][0] = 1;
            que.add(new int[]{0, 0, 1});
        }
    } else {
        if (S[0][N - 1] == c) {
            len[0][N - 1] = 0;
            que.add(new int[]{0, N - 1, 0});
        } else {
            len[0][N - 1] = 1;
            que.add(new int[]{0, N - 1, 1});
        }
    }

    while (!que.isEmpty()) {
        var cur = que.poll();
        int i = cur[0];
        int j = cur[1];

        List<int[]> sur = new ArrayList<>();
        if (0 < i)
            sur.add(new int[]{i - 1, j});
        if (0 < j)
            sur.add(new int[]{i, j - 1});
        if (i + 1 < N)
            sur.add(new int[]{i + 1, j});
        if (j + 1 < N)
            sur.add(new int[]{i, j + 1});

        for (var s : sur) {
            int l = S[s[0]][s[1]] == c ? 0 : 1;
            if (len[s[0]][s[1]] > cur[2] + l) {
                len[s[0]][s[1]] = cur[2] + l;
                if (l == 0)
                    que.addFirst(new int[]{s[0], s[1], len[s[0]][s[1]]});
                else
                    que.addLast(new int[]{s[0], s[1], len[s[0]][s[1]]});
            }
        }
    }

    return c == 'R' ? len[N - 1][N - 1] : len[0][0];
}
